import {modalFocusCandidates} from './modal-focus.mjs';
import {CAMPAIGN_MAP_POINTS,campaignRoadPath,mapRegionScrollLeft,mapSelectionScrollLeft} from './campaign-map-layout.mjs';
import {encounterEnemyIntel} from './enemy-intel.mjs';
import {CAMPAIGN_NAME,CAMPAIGN_REGIONS,campaignProgress,encounterBrief,canPrepareEncounter,terrainProfilePoints} from './campaign-atlas-model.mjs';
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>Number(value).toLocaleString();
const emblems={hearthwood:'M22 52V28m0 8C-5 40 5 4 22 11c16-17 35 6 15 17 18 6 8 21-15 13',bannerfen:'M5 44q15-14 30 0t30 0M8 54q15-14 30 0t24 0M30 40V4l25 10-25 10',frostpine:'M12 52 27 28H17L35 5l18 23H43l15 24ZM35 52v9',cinderlands:'m5 47 13-8 9 8 8-20 10 20 13-8 6 8-6 13H12ZM24 23l10-13 12 13'};
/** Finite, event-driven render; no frame listeners or mutation of campaign state. */
