export function renderCampaignRewards(host,result){
 if(!result){host.innerHTML='';return;}
 host.innerHTML=`<div class="campaign-reward-heading"><span class="eyebrow">${result.assisted?'ASSISTED RESULT':result.region.name.toUpperCase()}</span><strong>${escape(result.name)}</strong><p>${escape(result.headline)}</p></div><div class="campaign-reward-ledger"><span>Combat gold<b>+${number(result.combatGold)}</b></span><span>Victory bonus<b>+${number(result.bonusGold)}</b></span><span>Army spending<b>−${number(result.spentGold)}</b></span><span>Bonus XP<b>+${number(result.bonusXP)}</b></span></div>${result.rankGained?`<p class="campaign-rank-up">Hero rank increased by ${result.rankGained}</p>`:''}`;
}
